    /// S1-P-i35 — `Player.RemoveAllFishingBobbers` (`Player.cs:33576-33585`):
    /// kill every active bobber this owner controls (the sleep teardown,
    /// `PlayerSleepingHelper.cs:174`). The C# `Kill()`'s bobber arm
    /// (`Projectile.cs:71986-71994`) still gives a reeled catch, so the port
    /// rolls the stack on `final_level` and queues it for the world sim.
    pub fn remove_all_fishing_bobbers(
        &mut self,
        owner: u8,
        final_level: i32,
        rng: &mut dyn tr_core::loot::DropRng,
    ) {
        for i in 0..self.slots.len() {
            let p = &self.slots[i];
            if p.active && p.owner == owner && crate::projectile_bobber::handles(p.kind) {
                if let Some((item, stack)) =
                    crate::projectile_bobber::kill_hook(&mut self.slots[i], final_level, rng)
                {
                    self.pending_catches.push((owner, item, stack));
                }
                self.kill(i);
            }
        }
    }

    /// S1-P-i35 вЂ” `Player.ItemCheck_PullFishingBobbers` (`Player.cs:52368-
    /// 52399`): the use-start pull. Returns `false` when a live bobber exists
    /// (the use is a reel, NOT a cast вЂ” `ItemCheck_TryStartUse`'s gate
    /// `:52034-52037`). For each cast-state bobber (`ai[0] == 0`) it sets
    /// `ai[0] = 1`, clamps a wet bobber's `velocity.Y` to -10, and вЂ” when a
    /// bite is running (`ai[1] < 0 && localAI[1] != 0`) вЂ” runs the bait
    /// consumption + the pull decision. `bait` is the resolved bait slot
    /// `(type, power)` the caller found (`ConsumeBait`'s scan); `None` = no
    /// bait (the consume fails, the pull skips). The consumed bait's stack
    /// decrement and the ladybug luck ride the caller (the pool cannot reach
    /// the inventory); the returned `BaitUse` names what to drain.
    pub fn pull_fishing_bobbers(
        &mut self,
        owner: u8,
        bait: Option<(u16, i32)>,
        acc_tackle_box: bool,
        acc_fishing_line: bool,
        caught_rare: impl Fn(u16) -> i32,
        rng: &mut dyn tr_core::loot::DropRng,
    ) -> (bool, Option<BaitUse>) {
        let mut any = false;
        let mut bait_use = None;
        for i in 0..self.slots.len() {
            let p = &self.slots[i];
            if !p.active || p.owner != owner || !crate::projectile_bobber::handles(p.kind) {
                continue;
            }
            any = true;
            if p.ai[0] != 0.0 {
                continue;
            }
            // `:52385-52391` вЂ” the reel start.
            let p = &mut self.slots[i];
            p.ai[0] = 1.0;
            if p.wet && p.vel.y > -10.0 {
                p.vel.y = -10.0;
            }
            p.net_update = true;
            // `:52392-52395` вЂ” the bite pull (ConsumeBait then PullBobber).
            if p.ai[1] < 0.0 && p.local_ai[1] != 0.0 {
                let Some((bait_type, bait_power)) = bait else { continue };
                let local_ai1 = p.local_ai[1];
                let rare = if local_ai1 > 0.0 { caught_rare(local_ai1 as u16) } else { 0 };
                let consumed = tr_core::fishing::bait_consumed(
                    bait_type, bait_power, acc_tackle_box, local_ai1, rare, rng,
                );
                // `ConsumeBait` returns true once a bait slot was found (the
                // stack decrements only on `consumed`); the pull runs either
                // way (`:52392`'s gate is the find, not the consume).
                bait_use = Some(BaitUse { bait_type, consumed });
                let outcome = tr_core::fishing::pull_bobber_decision(
                    bait_type as i32, local_ai1, acc_fishing_line, rng,
                );
                match outcome {
                    tr_core::fishing::PullOutcome::SpawnDuke => {
                        p.wants_duke_spawn = true;
                        p.ai[0] = 2.0;
                    }
                    tr_core::fishing::PullOutcome::SpawnEnemy { npc, y_offset } => {
                        let (cx, cy) = p.center();
                        p.wants_fishing_enemy = Some((npc, cx, cy + y_offset as f32));
                        p.ai[0] = 2.0;
                    }
                    tr_core::fishing::PullOutcome::LineSnap => {
                        p.ai[0] = 2.0;
                    }
                    tr_core::fishing::PullOutcome::ReelIn => {
                        p.ai[1] = p.local_ai[1];
                    }
                }
                p.net_update = true;
            }
        }
        (!any, bait_use)
    }

    /// S1-P-i35 вЂ” the pull's enemy spawn drain (`Player.cs:52415-52437`):
    /// `(npc_type, x, y)` the world sim resolves into the NPC vec.
    pub fn drain_fishing_enemies(&mut self) -> Vec<(i32, f32, f32)> {
        let mut out = Vec::new();
        for p in self.slots.iter_mut() {
            if let Some(req) = p.wants_fishing_enemy.take() {
                out.push(req);
            }
        }
        out
    }

    /// S1-P-i35 вЂ” the pull's Duke Fishron spawn drain (`Player.cs:52403-
    /// 52414`): the owner ids that requested `SpawnOnPlayer(plr, 370)`.
    pub fn drain_duke_spawns(&mut self) -> Vec<u8> {
        let mut out = Vec::new();
        for p in self.slots.iter_mut() {
            if p.wants_duke_spawn {
                p.wants_duke_spawn = false;
                out.push(p.owner);
            }
        }
        out
    }

    /// S1-P-i06 вЂ” the spear family's owner snapshot (`AI_019_Spears`'s
    /// `Main.player[owner]` reads). The world-sim pass builds it per fixed
    /// step from the live player + the swing timers (the `set_disco` setter
    /// pattern). `None` clears the link (the arm's orphan guard).
    pub fn set_spear_owner(&mut self, owner: Option<crate::projectile_ai_spear::SpearOwner>) {
        self.spear_owner = owner;
    }

    /// S1-P-i06 вЂ” drain the lances' channel-hold write-back
    /// (`SetDummyItemTime(third)`, `Projectile.cs:45941`): the world-sim pass
    /// re-arms `app.swing`/`app.item_time` to this many ticks. `None` when no
    /// lance held this tick.
    pub fn take_spear_hold(&mut self) -> Option<i32> {
        self.pending_spear_hold.take()
    }

    /// W4-d14 вЂ” drain the monk staff swings' `player.reuseDelay` write
    /// (`Projectile.cs:69457`/`:69531`): the world-sim pass re-arms
    /// `app.reuse_delay` to this many ticks. `None` when no swing died.
    pub fn take_monk_reuse(&mut self) -> Option<i32> {
        self.pending_monk_reuse.take()
    }

    /// W4-d15 вЂ” the DD2 slice's owner snapshot (`AI_142`'s
    /// `Main.player[owner]` reads, `Projectile.cs:69819-69844`). The
    /// world-sim pass builds it per fixed step from the live player + the
    /// swing timers (the `set_spear_owner` pattern). `None` clears the
    /// link (the arm's orphan guard).
    pub fn set_dd2_owner(&mut self, owner: Option<crate::projectile_ai_dd2::Dd2Owner>) {
        self.dd2_owner = owner;
    }

    /// W4-d15 вЂ” drain the 142 arm's player writes: `(heldProj, reuseDelay)`
    /// per fired arm, in slot order (`Projectile.cs:69822`/`:69966`). The
    /// world-sim pass applies them after the step.
    pub fn take_dd2_writes(&mut self) -> Vec<(Option<i32>, Option<i32>)> {
        std::mem::take(&mut self.pending_dd2_writes)
    }

    /// W4-d15 вЂ” drain the 144 arm's 1050 shake-tick effect requests
    /// (`Projectile.cs:70217-70229`), in slot order. The world-sim pass
    /// resolves the dust/sound/drop effects on the `UpdateProjectiles`
    /// stream (the arm's three draws already ran inline).
    pub fn take_dd2_shakes(&mut self) -> Vec<crate::projectile_ai_dd2::Dd2Shake> {
        std::mem::take(&mut self.pending_dd2_shakes)
    }

    /// `AI_GetMyGroupIndexAndFillBlackList` (`Projectile.cs:51895-51911`) plus
    /// the two same-kind separation loops `AI_158` runs
    /// (`:48823-48846` at `0.025f`/`width * 3` and `:48881-48902` at
    /// `0.05f`/`width`) вЂ” pre-computed here because the slot arm cannot read
    /// the pool. Returns `(group index, attack-band push, home-band push)`.
    ///
    /// The group index counts only the perched siblings for 759
    /// (`projectile.frame == projFrames - 1`, `:51902`); the 1119 arm of the
    /// same test has no ported kind.
    fn baby_bird_group(&self, me: usize) -> (i32, Vec2, Vec2) {
        let this = &self.slots[me];
        let frames = proj_frames(this.kind) as i32;
        let mut index = 0i32;
        let mut sep_attack = Vec2::ZERO;
        let mut sep_home = Vec2::ZERO;
        for (i, other) in self.slots.iter().enumerate() {
            if !other.active || other.owner != this.owner || other.kind != this.kind {
                continue;
            }
            // `:51902` вЂ” the 759 group only counts perched birds.
            if other.kind == BABY_BIRD && other.frame != frames - 1 {
                continue;
            }
            if me > i {
                index += 1;
            }
            if i == me {
                continue;
            }
            let manhattan =
                (this.pos.x - other.pos.x).abs() + (this.pos.y - other.pos.y).abs();
            // `:48827` вЂ” the attack band, `width * 3` wide, 0.025f per axis.
            if manhattan < this.w * 3.0 {
                sep_attack.x += if this.pos.x < other.pos.x { -0.025 } else { 0.025 };
                sep_attack.y += if this.pos.y < other.pos.y { -0.025 } else { 0.025 };
            }
            // `:48883` вЂ” the home band, `width` wide, 0.05f per axis.
            if manhattan < this.w {
                sep_home.x += if this.pos.x < other.pos.x { -0.05 } else { 0.05 };
                sep_home.y += if this.pos.y < other.pos.y { -0.05 } else { 0.05 };
            }
        }
        (index, sep_attack, sep_home)
    }

    /// W4-d18 — `AI_GetMyGroupIndexAndFillBlackList(null, ...)`
    /// (`Projectile.cs:51895-51911`), the titanium shard's `(index,
    /// totalIndexesInGroup)` pair: the count of this owner's active
    /// same-kind slots at lower indices, and the group total. The 759
    /// perch gate and the 1119 localAI[0] gate of `:51902` never fire for
    /// the 908 (the only kind this helper serves — the baby bird keeps
    /// its own [`ProjectilePool::baby_bird_group`]). The blacklist out-arg
    /// stays null at the call site (`:45334`), so nothing is filled.
    fn shard_group(&self, me: usize) -> (i32, i32) {
        let this = &self.slots[me];
        let mut index = 0i32;
        let mut total = 0i32;
        for (i, other) in self.slots.iter().enumerate() {
            if other.active && other.owner == this.owner && other.kind == this.kind {
                if me > i {
                    index += 1;
                }
                total += 1;
            }
        }
        (index, total)
    }

    /// Sets the slot's crit flag (the throw path rolls it at spawn time).
    /// The `ProjectileKey` a slot's current occupant would travel under
    /// (`Projectile.cs:10854`'s key mint).
    pub fn key_of(&self, slot: usize) -> i32 {
        let p = &self.slots[slot];
        crate::net::projectile_key(p.owner, slot, p.generation)
    }

    /// `((ProjectileKey)this.ai[1]).TryGetActive(expectedType)` (`Projectile.cs:34824`,
    /// `DataStructures/ProjectileKey.cs:100-108`): the ai slot carries the key's
    /// **raw bit pattern** reinterpreted as f32 вЂ” the C# union's `floatBits`
    /// member, so `from_bits`/`to_bits` round-trip every 32 bits (a numeric
    /// cast would lose the generations above 2^24 the C# never loses). The
    /// lookup validates the packed slot's active + owner + generation and the
    /// expected kind; a recycled slot fails the generation match and the
    /// caller's arm kills, exactly as `TryLookup` (`Projectile.cs:632-639`)
    /// answers through the key equality. Shared by the key-linked pairs (the
    /// Nebula 617в†’618 pair and the Last Prism 633в†’632 pair, whose C# arms run
    /// the identical `TryGetActive` shape).
    fn key_parent(&self, key: f32, kind: u16) -> Option<&Projectile> {
        let (owner, slot, generation) = crate::net::projectile_key_parts(key.to_bits() as i32);
        let p = self.slots.get(slot)?;
        if p.active
            && p.kind == kind
            && p.owner == owner
            && p.generation == generation
            && crate::net::projectile_key(p.owner, slot, p.generation) == key.to_bits() as i32
        {
            Some(p)
        } else {
            None
        }
    }

    /// The 618 arm's view of its parent 617 вЂ” the position and centre the
    /// arm shifts by and steers toward (`Projectile.cs:34827-34852`).
    pub fn nebula_parent(&self, key: f32) -> Option<(Vec2, Vec2)> {
        self.key_parent(key, NEBULA_ARCANUM)
            .map(|p| (p.pos, Vec2::new(p.pos.x + p.w * 0.5, p.pos.y + p.h * 0.5)))
    }

    /// The 632 laser's view of its holder 633 (`((ProjectileKey)this.ai[1])
    /// .TryGetActive(633, out proj)`, `Projectile.cs:31428-31430`) вЂ” the
    /// snapshot the arm's envelope reads each tick.
    fn prism_parent(&self, key: f32) -> Option<PrismParent> {
        self.key_parent(key, LAST_PRISM).map(|p| PrismParent {
            center: Vec2::new(p.pos.x + p.w * 0.5, p.pos.y + p.h * 0.5),
            vel: p.vel,
            charge: p.ai[0],
            damage: p.damage,
        })
    }

    /// The `29` despawn: the slot dies only when the key matches its current
    /// occupant (`MessageBuffer.cs:1825-1850`'s key lookup).
    pub fn kill_remote(&mut self, slot: usize, owner: u8, generation: u16) {
        if slot >= MAX_PROJECTILES {
            return;
        }
        let p = &mut self.slots[slot];
        if p.active && p.owner == owner && p.generation == generation {
            p.active = false;
            p.time_left = 0;
        }
    }

    /// Creates or patches a slot from a `27 Projectile` body
    /// (`NewProjectileSetup` + the field assignment,
    /// `MessageBuffer.cs:1729-1755`): a key match patches in place, anything
    /// else (a fresh spawn, a recycled index) re-creates the slot with the
    /// wire's owner and generation.
    pub fn upsert_remote(&mut self, st: &crate::net::ProjectileState) {
        let (owner, slot, generation) = crate::net::projectile_key_parts(st.key);
        if slot >= MAX_PROJECTILES {
            return;
        }
        let matches = self.slots[slot].active
            && self.slots[slot].owner == owner
            && self.slots[slot].generation == generation;
        if !matches {
            let mut p = Projectile {
                active: true,
                kind: st.kind.max(0) as u16,
                owner,
                generation,
                ..Default::default()
            };
            p.pos = Vec2::new(st.x, st.y);
            p.vel = Vec2::new(st.vx, st.vy);
            p.damage = st.damage as i32;
            p.knock_back = st.knock_back;
            if let Some(v) = st.ai0 {
                p.ai[0] = v;
            }
            if let Some(v) = st.ai1 {
                p.ai[1] = v;
            }
            if let Some(v) = st.ai2 {
                p.ai[2] = v;
            }
            p.reset_trailing_rings();
            self.slots[slot] = p;
            let base = slot * 256;
            self.local_immunity[base..base + 256].fill(0);
            return;
        }
        let p = &mut self.slots[slot];
        p.pos = Vec2::new(st.x, st.y);
        p.vel = Vec2::new(st.vx, st.vy);
        if st.kind >= 0 {
            p.kind = st.kind as u16;
        }
        p.damage = st.damage as i32;
        p.knock_back = st.knock_back;
        if let Some(v) = st.ai0 {
            p.ai[0] = v;
        }
        if let Some(v) = st.ai1 {
            p.ai[1] = v;
        }
        if let Some(v) = st.ai2 {
            p.ai[2] = v;
        }
    }

    pub fn set_crit(&mut self, slot: usize, crit: bool) {
        if let Some(p) = self.slots.get_mut(slot) {
            p.crit = crit;
        }
    }

    /// `Main.projectile[num].noDropItem = true` вЂ” the multi-shot bows stamp it
