    /// W4-c8 sweep — `Damage_PVE_Inner`'s hostile half
    /// (`Projectile.cs:12606-12611`): `flag2 = friendly &&
    /// !dontTakeDamageFromHostiles`; a hostile shot hits a friendly NPC
    /// only while flag2 holds. The field's SetDefaults rows: 374/375
    /// true (`NPC.cs:13775`/`:13794`), everything else false (`:8501`).
    /// WRITTEN, NOT RUN (code-only mode).
    #[test]
    fn w4_c8_hostile_shots_refuse_the_dont_take_damage_from_hostiles_carriers() {
        let w = ground();
        // The SetDefaults rows: the TruffleWorm pair carries the flag,
        // the plain Worm does not.
        let t = Npc::new(NpcKind::TruffleWorm, 100.0, 100.0, 1, 0.0);
        assert!(t.dont_take_damage_from_hostiles, ":13775");
        let d = Npc::new(NpcKind::TruffleWormDigger, 100.0, 100.0, 1, 0.0);
        assert!(d.dont_take_damage_from_hostiles, ":13794");
        let worm = Npc::new(NpcKind::Worm, 100.0, 100.0, 1, 0.0);
        assert!(!worm.dont_take_damage_from_hostiles, ":8501 reset");
        // The Transform refresh keeps the flag across the 374→375 dig.
        let mut t2 = Npc::new(NpcKind::TruffleWorm, 100.0, 100.0, 1, 0.0);
        let player0 = crate::player::Player::spawn(&w);
        t2.transform_to_kind(&w, &player0, NpcKind::TruffleWormDigger);
        assert!(t2.dont_take_damage_from_hostiles, "the dig keeps the row");
        // The gate: a friendly carrier refuses the hostile shot. Force
        // friendly true (the wild-critter window shape — the pair is
        // non-catchable so production friendly is false and the gate is
        // inert; this pins the FLAG's mechanics for the future carriers).
        let mut carrier = Npc::new(NpcKind::TruffleWorm, 100.0, 100.0, 1, 0.0);
        carrier.friendly = true;
        carrier.catchable_immunity = 0; // no window re-arm
        let mut npcs = vec![carrier];
        let mut player = crate::player::Player::spawn(&w);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn_hostile(SHURIKEN, Vec2::new(108.0, 108.0), Vec2::ZERO, 10, 5.0)
            .expect("the hostile slot");
        assert!(!pool.slots[slot].friendly, "the hostile spawn");
        let hp = npcs[0].hp;
        pool.update(
            &mut w.clone(),
            &mut npcs,
            None,
            None,
            Some(&mut player),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
        assert_eq!(npcs[0].hp, hp, "flag2 false — the hostile hit refuses");
        // The same carrier WITHOUT the flag takes the hostile hit
        // (flag2 true — the C# hostile shots damage friendly critters).
        let mut plain = Npc::new(NpcKind::Worm, 100.0, 100.0, 1, 0.0);
        plain.friendly = true;
        plain.catchable_immunity = 0;
        assert!(!plain.dont_take_damage_from_hostiles);
        let mut npcs2 = vec![plain];
        let mut pool2 = ProjectilePool::new();
        pool2
            .spawn_hostile(SHURIKEN, Vec2::new(103.0, 100.0), Vec2::ZERO, 10, 5.0)
            .expect("the hostile slot");
        let hp2 = npcs2[0].hp;
        pool2.update(
            &mut w.clone(),
            &mut npcs2,
            None,
            None,
            Some(&mut player),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
        assert!(npcs2[0].hp < hp2, "flag2 true — the hostile hit lands");
    }

    /// BUG-23: the friendly refusal on the player's shots —
    /// BUG-23: the friendly refusal on the player's shots вЂ”
    /// `Damage_PVE_Inner` (`Projectile.cs:12601-12608`). A shot passes a town
    /// NPC, the doll-owned Guide arm lets it through, and the helper's arm
    /// matrix covers the Rotten Egg and the bound forms.
    #[test]
    fn bug_23_projectiles_refuse_the_friendly_npcs() {
        let w = ground();
        let mut guide = Npc::spawn_guide(&w, 30).expect("the Guide spawns");
        guide.x = 100.0;
        guide.y = 100.0;
        // The Guide's box is 18x40 at (100, 100); the shot's centre sits at
        // `pos + 3` вЂ” (108, 108) puts it inside.
        let mut npcs = vec![guide];
        let mut player = crate::player::Player::spawn(&w);
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn(SHURIKEN, 0, Vec2::new(108.0, 108.0), Vec2::ZERO, 10, 5.0, false)
            .expect("the slot");
        let hp = npcs[0].hp;
        pool.update(
            &mut w.clone(),
            &mut npcs,
            None,
            None,
            Some(&mut player),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
        assert_eq!(npcs[0].hp, hp, "the shot passes through the Guide");
        assert!(pool.slots[slot].active, "and the shot is not consumed");
        // The worn Guide Voodoo Doll arms the arm (`Player.cs:15124`).
        let mut npcs2 = vec![Npc::spawn_guide(&w, 30).expect("the Guide spawns")];
        npcs2[0].x = 100.0;
        npcs2[0].y = 100.0;
        let mut player2 = crate::player::Player::spawn(&w);
        player2.equipped[3] = 267;
        let mut pool2 = ProjectilePool::new();
        pool2
            .spawn(SHURIKEN, 0, Vec2::new(108.0, 108.0), Vec2::ZERO, 10, 5.0, false)
            .expect("the slot");
        let hp = npcs2[0].hp;
        pool2.update(
            &mut w.clone(),
            &mut npcs2,
            None,
            None,
            Some(&mut player2),
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
        assert!(npcs2[0].hp < hp, "the doll-armed Guide takes the shot");
        // The helper's matrix: every friendly kind refuses a plain shot, the
        // Rotten Egg (318) gets through everything, the doll arms only cover
        // the Guide (22) and the Clothier (54), and the six bound forms have
        // no arm at all (`isLikeATownNPC` does not cover them).
        let bound = Npc::spawn_town(&w, 30, NpcKind::BoundGoblin).expect("the bound goblin spawns");
        let clothier = Npc::spawn_town(&w, 30, NpcKind::Clothier).expect("the Clothier spawns");
        let slime = one_npc(&w);
        assert!(refuses_friendly(&npcs[0], SHURIKEN, false, false));
        assert!(!refuses_friendly(&npcs[0], ROTTEN_EGG, false, false));
        assert!(!refuses_friendly(&npcs[0], SHURIKEN, true, false));
        assert!(!refuses_friendly(&clothier, SHURIKEN, false, true));
        assert!(refuses_friendly(&clothier, SHURIKEN, true, false));
        assert!(refuses_friendly(&bound, SHURIKEN, true, true));
        assert!(!refuses_friendly(&bound, ROTTEN_EGG, false, false));
        assert!(!refuses_friendly(&slime, SHURIKEN, false, false));
    }

    /// One pool update plus the per-NPC decay the NPC update would run
    /// (`NPC.cs:90454-90459`), so multi-tick tests see the gates age.
    fn tick(world: &mut World, pool: &mut ProjectilePool, npc: &mut Npc) {
        for v in npc.immune.iter_mut() {
            *v = (*v - 1).max(0);
        }
        npc.hurt_cd = (npc.hurt_cd - 1.0 / 60.0).max(0.0);
        pool.update(
            world,
            std::slice::from_mut(npc),
            None,
            None,
            None,
            YoyoInputs::default(),
            FlailInputs::default(),
            &mut tr_core::tile_light::FastRandom::new(7),
            0,
            true,
        );
    }

    #[test]
    fn spawn_takes_the_first_free_slot_and_recycles_the_dead() {
        let mut pool = ProjectilePool::new();
        let a = pool.spawn(SHURIKEN, 0, Vec2::ZERO, Vec2::ZERO, 10, 0.0, false);
        let b = pool.spawn(SHURIKEN, 0, Vec2::ZERO, Vec2::ZERO, 10, 0.0, false);
        assert_eq!((a, b), (Some(0), Some(1)));
        pool.slots_mut()[0].active = false;
        pool.slots_mut()[0].time_left = 0;
        assert_eq!(
            pool.spawn(SHURIKEN, 0, Vec2::ZERO, Vec2::ZERO, 10, 0.0, false),
            Some(0)
        );
    }

    #[test]
    fn full_pool_recycles_the_lowest_time_left() {
        let mut pool = ProjectilePool::new();
        for i in 0..MAX_PROJECTILES {
            pool.spawn(SHURIKEN, 0, Vec2::ZERO, Vec2::ZERO, 10, 0.0, false);
            pool.slots_mut()[i].time_left = 1000 - (i % 10) as i32;
        }
        // The lowest timeLeft (991) sits at slot 9 вЂ” `FindOldestProjectile`
        // scans front-to-back keeping the strict minimum (`:10811-10821`).
        assert_eq!(pool.slots()[9].time_left, 991);
        assert_eq!(
            pool.spawn(SHURIKEN, 0, Vec2::ZERO, Vec2::ZERO, 10, 0.0, false),
            Some(9)
        );
    }

