    #[test]
    fn the_last_prism_laser_applies_five_tick_immunity_in_both_walks() {
        // W3-i11 вЂ” `Projectile.cs:13992-13995`: the Last Prism laser (632)
        // sets `immune[owner] = GetSlowMagicUseTime(5)`; the `slowMagicUse`
        // state is unported (`Player.cs:47019-47026` returns the original
        // time when the flag is false), so the window is 5. The old walks
        // fell through to the stock 10-tick window (penetrate в€’1). Both the
        // plain PVE pass and the boxed `Damage()` walk carry the arm, in
        // the C# if/else position (after id-static, before 634/635/659).
        let w = ground();
        // The plain walk.
        {
            let mut pool = ProjectilePool::new();
            let mut npc = one_npc(&w);
            npc.x = 20.0 * TILE_PX;
            npc.y = 24.0 * TILE_PX;
            npc.hp = 10_000;
            npc.max_hp = 10_000;
            let slot = pool
                .spawn_with_data_ai(LAST_PRISM_LASER, npc.x, npc.y, 0.0, 0.0, 10, 0.0, 0.0, 0.0)
                .unwrap();
            let mut rng = tr_core::tile_light::FastRandom::new(7);
            pool.damage_pve(&w, slot, std::slice::from_mut(&mut npc), None, None, None, &mut rng);
            assert!(npc.hp < 10_000, "the laser lands");
            assert_eq!(npc.immune[0], 5, "the 5-tick per-type arm (plain walk)");
            // penetrate в€’1 keeps the shot alive, but the 5-tick window
            // refuses the immediate re-hit (`:12620-12624`).
            let hp_after = npc.hp;
            pool.damage_pve(&w, slot, std::slice::from_mut(&mut npc), None, None, None, &mut rng);
            assert_eq!(npc.hp, hp_after, "the per-owner window refuses the re-hit");
        }
        // The boxed walk вЂ” same arm, same position in the if/else chain.
        {
            let mut pool = ProjectilePool::new();
            let mut npc = one_npc(&w);
            npc.x = 20.0 * TILE_PX;
            npc.y = 24.0 * TILE_PX;
            npc.hp = 10_000;
            npc.max_hp = 10_000;
            let slot = pool
                .spawn_with_data_ai(LAST_PRISM_LASER, npc.x, npc.y, 0.0, 0.0, 10, 0.0, 0.0, 0.0)
                .unwrap();
            let mut rng = tr_core::tile_light::FastRandom::new(7);
            pool.damage_pve_boxed(
                slot, std::slice::from_mut(&mut npc), (false, false), &mut rng, 0.0);
            assert!(npc.hp < 10_000, "the laser lands (boxed walk)");
            assert_eq!(npc.immune[0], 5, "the 5-tick per-type arm (boxed walk)");
        }
    }

    /// S1-C-8: `Damage()`'s PVE hit test is `Colliding(Damage_GetHitbox(),
    /// npc.getRect())` (`Projectile.cs:12499`/`:12654`) вЂ” a rectangle overlap,
    /// not the slot-centre point. A shot whose box covers the NPC while its
    /// centre sits outside the NPC's box still hits; the old
    /// `n.contains(centre)` test missed it.
    #[test]
    fn pve_hit_test_uses_the_projectile_box_not_its_centre() {
        let w = ground();
        let mut pool = ProjectilePool::new();
        let mut npc = one_npc(&w);
        // The slime's 24x18 box at (320, 384) в†’ [320,344]x[384,402].
        npc.x = 20.0 * TILE_PX;
        npc.y = 24.0 * TILE_PX;
        let slot = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX - 38.0, 24.0 * TILE_PX + 6.0),
                Vec2::ZERO,
                10,
                12.0,
                false,
            )
            .unwrap();
        // A 40x40 box anchored at pos (282, 390) в†’ [282,322]x[390,430]: it
        // overlaps the NPC's rect, but the centre (302, 410) is outside the
        // NPC's box (and outside its +4 point-test tolerance).
        pool.slots_mut()[slot].w = 40.0;
        pool.slots_mut()[slot].h = 40.0;
        let (cx, cy) = (20.0 * TILE_PX - 18.0, 24.0 * TILE_PX + 26.0);
        assert!(
            !npc.contains(cx, cy),
            "the centre is outside the NPC's box, so the point test misses"
        );
        let before = npc.hp;
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        pool.damage_pve(
            &w,
            slot,
            std::slice::from_mut(&mut npc),
            None,
            None,
            None,
            &mut rng,
        );
        assert!(
            npc.hp < before,
            "the overlapping box lands the hit even with the centre outside"
        );
    }

