    /// S1-P-i49 вЂ” the summon prefixes' armor penetration reaches the strike:
    /// `ApplyStatsFromSource` copies `item.armorPenetration` onto the shot
    /// (`Projectile.cs:11128`), `Damage_PVE_Inner`'s `num5` adds it to the
    /// owner's `GetArmorPenetration` (`:12831`) and `checkArmorPenetration`
    /// lifts the rolled damage before the defense line (`:13632`).
    /// WRITTEN NOT RUN (code-only mode).
    #[test]
    fn s1_p_i49_the_prefix_armor_penetration_lifts_the_pve_strike() {
        let w = ground();
        let mut pool = ProjectilePool::new();
        let mut npc = one_npc(&w);
        npc.x = 20.0 * TILE_PX;
        npc.y = 24.0 * TILE_PX;
        npc.hp = 500;
        npc.max_hp = 500;
        npc.defense_override = Some(200); // the raw 40 floors at 1 without pen
        let mut player = crate::player::Player::spawn(&w);
        let slot = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                40,
                12.0,
                false,
            )
            .unwrap();
        // The Eager (95) row: arpen 25, no other stat (`Item.cs:942-944`).
        let arpen = crate::prefix::prefixed_stats(1157, 95).unwrap().armor_penetration;
        assert_eq!(arpen, 25);
        pool.set_armor_penetration(slot, arpen);
        let before = npc.hp;
        let mut rng = tr_core::tile_light::FastRandom::new(7);
        pool.damage_pve(
            &w,
            slot,
            std::slice::from_mut(&mut npc),
            None,
            Some(player.center()),
            Some(&mut player),
            &mut rng,
        );
        // `checkArmorPenetration(25, 0, 200)` = 25/2 = 12 (`NPC.cs:81148`);
        // the В±15% DamageVar rolls 40 into [34, 46], + 12 в€’ 100 stays under
        // the floor, so the strike lands exactly 1.
        let lost = before - npc.hp;
        assert_eq!(lost, 1, "the pen lifts the pre-defense sum, still floored");
        // The observable lift: at defense 80 the no-pen strike floors at 1
        // while the +12 pen pushes (34..46 + 12) в€’ 40 into [6, 18].
        let mut npc3 = one_npc(&w);
        npc3.x = 20.0 * TILE_PX;
        npc3.y = 24.0 * TILE_PX;
        npc3.hp = 500;
        npc3.max_hp = 500;
        npc3.defense_override = Some(80);
        let slot3 = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                40,
                12.0,
                false,
            )
            .unwrap();
        pool.set_armor_penetration(slot3, arpen);
        let mut rng3 = tr_core::tile_light::FastRandom::new(7);
        pool.damage_pve(
            &w,
            slot3,
            std::slice::from_mut(&mut npc3),
            None,
            Some(player.center()),
            Some(&mut player),
            &mut rng3,
        );
        let lost3 = 500 - npc3.hp;
        assert!(
            (6..=18).contains(&lost3),
            "the +12 penetration lifts the strike past the floor: lost {lost3}"
        );
        // The no-owner lane keeps the pre-existing no-pen behaviour (the
        // C# gates on `ownedBySomeone`, `:13630`).
        let mut npc2 = one_npc(&w);
        npc2.x = 20.0 * TILE_PX;
        npc2.y = 24.0 * TILE_PX;
        npc2.hp = 500;
        npc2.max_hp = 500;
        npc2.defense_override = Some(200);
        let slot2 = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                40,
                12.0,
                false,
            )
            .unwrap();
        pool.set_armor_penetration(slot2, arpen);
        let mut rng2 = tr_core::tile_light::FastRandom::new(7);
        pool.damage_pve(
            &w,
            slot2,
            std::slice::from_mut(&mut npc2),
            None,
            None,
            None,
            &mut rng2,
        );
        assert_eq!(npc2.hp, 499, "the ownerless shot keeps the floor of 1");
    }

    /// S1-C-8: `Damage_GetHitbox()` (`Projectile.cs:14959-15023`) вЂ” the base
    /// rect is the truncated `position`/`width`/`height`, and the kind/state
    /// arms inflate it. Pins the arms reachable from the pool's rows.
    #[test]
    fn damage_hitbox_ports_the_base_rect_and_the_inflate_arms() {
        let mut pool = ProjectilePool::new();
        let slot = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(100.9, 200.4),
                Vec2::ZERO,
                10,
                0.0,
                false,
            )
            .unwrap();
        // `:14961`: `new Rectangle((int)position.X, (int)position.Y, width, height)`.
        assert_eq!(
            pool.damage_hitbox(slot),
            tr_core::whip::Rect::new(100, 200, 6, 6)
        );
        // `:14984-14987`: type 101 inflates 30 px on each side.
        pool.slots_mut()[slot].kind = 101;
        assert_eq!(
            pool.damage_hitbox(slot),
            tr_core::whip::Rect::new(70, 170, 66, 66)
        );
        // `:15014-15017`: every aiStyle-29 (gem-staff) shot pads by 4 px.
        pool.slots_mut()[slot].kind = GEM_BOLT_AMETHYST;
        assert_eq!(
            pool.damage_hitbox(slot),
            tr_core::whip::Rect::new(96, 196, 14, 14)
        );
        // `:14996-15000`: type 85's `localAI[0]` 0..72 в†’ 10..40 px ramp.
        pool.slots_mut()[slot].kind = 85;
        pool.slots_mut()[slot].local_ai[0] = 0.0;
        assert_eq!(
            pool.damage_hitbox(slot),
            tr_core::whip::Rect::new(90, 190, 26, 26)
        );
        pool.slots_mut()[slot].local_ai[0] = 72.0;
        assert_eq!(
            pool.damage_hitbox(slot),
            tr_core::whip::Rect::new(60, 160, 86, 86)
        );
    }

    #[test]
    fn local_immunity_gates_rehits_for_the_cooldown() {
        let mut world = ground();
        let mut pool = ProjectilePool::new();
        let mut npc = one_npc(&world);
        npc.x = 20.0 * TILE_PX;
        npc.y = 24.0 * TILE_PX;
        npc.defense_override = Some(0);
        let slot = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                10,
                12.0,
                false,
            )
            .unwrap();
        // A 3-hit piercing shot with the 12-tick local cooldown (the C# sets
        // `usesLocalNPCImmunity` + `localNPCHitCooldown = 12` in SetDefaults).
        pool.set_immunity(slot, 3, true, 12, false, -1);
        let hp0 = npc.hp;
        tick(&mut world, &mut pool, &mut npc);
        assert!(pool.slots()[slot].active);
        assert_eq!(pool.slots()[slot].penetrate, 2);
        let hit = hp0 - npc.hp;
        assert!(hit > 0, "first hit must deal damage");
        // The local entry decays per update (`:17270-17277`) and gates every
        // re-hit until it reaches zero; a local hit zeroes
        // `NPC.immune[owner]` (`:14108-14109`). Set to 12 on tick 1, it frees
        // the gate on tick 13.
        for _ in 0..11 {
            tick(&mut world, &mut pool, &mut npc);
        }
        assert_eq!(npc.hp, hp0 - hit, "gated for the 11 middle ticks");
        tick(&mut world, &mut pool, &mut npc);
        assert_eq!(npc.hp, hp0 - 2 * hit, "tick 13: the local entry expired");
        assert_eq!(pool.slots()[slot].penetrate, 1);
    }

    #[test]
    fn default_penetrating_hits_use_the_owner_immunity_of_10() {
        let mut world = ground();
        let mut pool = ProjectilePool::new();
        let mut npc = one_npc(&world);
        npc.x = 20.0 * TILE_PX;
        npc.y = 24.0 * TILE_PX;
        npc.defense_override = Some(0);
        let slot = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                10,
                12.0,
                false,
            )
            .unwrap();
        pool.set_immunity(slot, 5, false, -2, false, -1);
        let hp0 = npc.hp;
        tick(&mut world, &mut pool, &mut npc);
        let hit = hp0 - npc.hp;
        assert!(hit > 0, "first hit must deal damage");
        assert_eq!(npc.immune[0], 10, "`:14117`");
        for _ in 0..9 {
            tick(&mut world, &mut pool, &mut npc);
        }
        assert_eq!(npc.hp, hp0 - hit, "the owner gate holds for the 10 ticks");
        assert_eq!(pool.slots()[slot].penetrate, 4, "tick 1 already spent one");
        tick(&mut world, &mut pool, &mut npc);
        assert_eq!(npc.hp, hp0 - 2 * hit, "the 10th decay tick freed the gate");
        assert_eq!(npc.immune[0], 10, "re-applied");
        assert_eq!(
            pool.slots()[slot].penetrate,
            3,
            "the freed gate landed a hit"
        );
    }

    #[test]
    fn id_static_immunity_is_shared_across_slots_of_the_same_kind() {
        let mut world = ground();
        let mut pool = ProjectilePool::new();
        let mut npc = one_npc(&world);
        npc.x = 20.0 * TILE_PX;
        npc.y = 24.0 * TILE_PX;
        npc.defense_override = Some(0);
        let a = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                10,
                12.0,
                false,
            )
            .unwrap();
        let b = pool
            .spawn(
                SHURIKEN,
                0,
                Vec2::new(20.0 * TILE_PX, 24.0 * TILE_PX),
                Vec2::ZERO,
                10,
                12.0,
                false,
            )
            .unwrap();
        pool.set_immunity(a, 2, false, -2, true, 30);
        pool.set_immunity(b, 2, false, -2, true, 30);
        // The ported aiStyle-2 arm (`Projectile.cs:23659-23674`) starts falling
        // at `ai[0] >= 20f`, which walks the shot out of the zombie's 18 px box
        // inside the stamp's 30-tick window. This test pins the stamp, not the
        // flight, so the age counters start 100 ticks short of the gravity.
        pool.slots[a].ai[0] = -100.0;
        pool.slots[b].ai[0] = -100.0;
        let hp0 = npc.hp;
        tick(&mut world, &mut pool, &mut npc);
        // Both slots overlap the NPC in the same tick: the ID-static stamp
        // written by the first hit (`:13972`) gates the second.
        let hit = hp0 - npc.hp;
        assert!(hit > 0, "exactly one slot lands on the shared stamp");
        let stamp = *pool.id_static.get(&(SHURIKEN, 0)).unwrap();
        assert!(stamp > pool.update_count, "the stamp must still be live");
        for _ in 0..31 {
            tick(&mut world, &mut pool, &mut npc);
        }
        assert!(
            npc.hp < hp0 - hit,
            "the expired stamp (`<= GameUpdateCount`, `:604-607`) allowed a re-hit"
        );
    }

