        assert!((p.vel.x - 4.0 * 0.98).abs() < 1e-6, "the grounded 0.98 drag (`:27009`)");
        assert!((p.vel.y - 0.1).abs() < 1e-6, "the dry 0.1 gravity (`:27042`)");
        assert!((p.rot - 0.02 * 4.0).abs() < 1e-6, "the 0.02·vx spin (`:27006`)");
