        assert_eq!(yoyo_top_speed(WOOD_YOYO), 9.0);
        assert_eq!(yoyo_top_speed(KRAKEN_YOYO), 22.0);
        assert_eq!(yoyo_top_speed(TERRARIAN_YOYO), 17.5);
        // The factory default for an unlisted kind in the range/top-speed
