        let mut npc = Npc::spawn_slime_sky(10.0 * TILE_PX + 200.0, 10.0 * TILE_PX, SlimeVariant::Blue);
        npc.hp = npc.max_hp;
        // Park the launch counter at 30 so the scan runs on the next sub-step.
        pool.slots_mut()[slot].ai[0] = 30.0;
