        assert!(d.melee, "`:10348`");
        assert_eq!(proj_frames(SKY_DRAGONS_FURY_ELECTROSPHERE), 4, "`Main.cs:8559`");
        // The 443 sibling shares the sheet + the aiStyle-77 arm.
